import{_ as a,o as e,c as i,a2 as n}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),d={name:"guide/index.md"};function r(s,t,l,o,p,c){return e(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><blockquote><p>🌈 基于 Vue3.x + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的后台管理系统，支持自动注册路由、无限子级权限管理等，无需授权即可免费商用，希望能帮助大家实现快速开发。</p><p>—— 项目 README</p></blockquote><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>搭建一套商业级后台，往往要反复处理布局、路由、权限、国际化、主题、请求封装这些「每次都要做一遍」的基础工作。BirdAdmin 把这些基础设施预先搭好，让你把时间花在业务页面上。</p><p>README 里对它的期望很直接：<strong>使用流行技术栈快速创建商业级后台管理系统</strong>。技术选型不追新求异，而是选择生态成熟、招人容易、资料丰富的主流方案。</p><h2 id="项目速览" tabindex="-1">项目速览 <a class="header-anchor" href="#项目速览" aria-label="Permalink to &quot;项目速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>名称</td><td>BirdAdmin</td></tr><tr><td>版本</td><td>1.0.0</td></tr><tr><td>定位</td><td>后台管理系统前端模板</td></tr><tr><td>主要技术</td><td>Vue 3 · Vite · TypeScript · Element Plus · Pinia · UnoCSS</td></tr><tr><td>后端方案</td><td>README 标注为 ThinkPHP8（前端仓库不含后端代码）</td></tr><tr><td>Node 要求</td><td><code>^20.19.0 || &gt;=22.12.0</code></td></tr><tr><td>包管理器</td><td>pnpm</td></tr><tr><td>开发端口</td><td>9094</td></tr><tr><td>开源协议</td><td>Apache-2.0，无需授权即可免费商用</td></tr><tr><td>仓库地址</td><td><a href="https://gitee.com/web_akai/bird-admin" target="_blank" rel="noreferrer">gitee.com/web_akai/bird-admin</a></td></tr></tbody></table><h2 id="架构视角" tabindex="-1">架构视角 <a class="header-anchor" href="#架构视角" aria-label="Permalink to &quot;架构视角&quot;">​</a></h2><p>从当前仓库的源码结构看，前端被拆成几层清晰的职责：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>入口层     main.ts → 注册插件 / 路由 / 全局样式</span></span>
<span class="line"><span>配置层     config、enums、types、.env*</span></span>
<span class="line"><span>能力层     router、store、utils/http、locales、plugins</span></span>
<span class="line"><span>视图层     layout、components、views</span></span>
<span class="line"><span>资源层     assets（图标 / 图片 / 样式）、public</span></span>
<span class="line"><span>构建层     build/vite、vite.config.ts、uno.config.ts</span></span></code></pre></div><ul><li><strong>前后端分离</strong>：仓库只包含前端代码，接口通过 <code>VITE_API_URL</code> 与 <code>/api</code> 代理对接，代码与部署都可以前后端独立进行。</li><li><strong>约定优于配置</strong>：路由模块、组件、API 的自动导入减少了大量样板代码，详见<a href="/guide/project-structure.html">目录结构</a>与<a href="/guide/routing.html">路由与权限</a>。</li><li><strong>开箱即用的设置</strong>：主题（跟随系统深浅色）、语言（默认简体中文）、组件尺寸、水印等都有默认配置。</li></ul><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li>需要快速交付中后台系统的前端 / 全栈开发者；</li><li>想学习 Vue 3 组合式 API、TypeScript、Vite 工程化实践的同学；</li><li>只需要一套干净前端代码、自行对接任意后端服务的团队。</li></ul><p>如果你只想做纯前端开发，README 里也写得很明确：<strong>不需要会任何后端代码</strong>，把 BAdmin 当作学习与资源的社群即可。</p><h2 id="关于这份文档" tabindex="-1">关于这份文档 <a class="header-anchor" href="#关于这份文档" aria-label="Permalink to &quot;关于这份文档&quot;">​</a></h2><p>本站以项目 README 为内容主干，并补充了从当前仓库可直接核对的信息（依赖版本、目录结构、环境变量、脚本命令等）。凡是 README 与源码不一致的地方，文档都会显式标注，避免照着旧描述踩坑。</p><div class="info custom-block"><p class="custom-block-title">仍在开发中的能力</p><p>README 提到的「无限子级权限管理」「按需一键安装基础设施模块」「行业完整应用」属于项目规划中的目标；当前仓库可见的实现范围请以<a href="/guide/routing.html">路由与权限</a>与<a href="/guide/tech-stack.html">技术栈与依赖</a>中的说明为准。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想先看亮点 → <a href="/guide/features.html">主要特性</a></li><li>想直接运行 → <a href="/guide/getting-started.html">快速开始</a></li><li>想了解技术细节 → <a href="/guide/tech-stack.html">技术栈与依赖</a></li></ul>`,19)])])}const m=a(d,[["render",r]]);export{u as __pageData,m as default};
